import time
import random
import numpy as np

N = 18
MIN_DISTANCE = 6

def construct():
    """
    Constructs the largest possible binary code of length 18 and distance 6.
    Strategy: Directly construct the [18,9,6] extended quadratic residue code.
    This code is known to be optimal (A_2(18,6) = 512).
    """
    # The [18,9,6] code is the extended QR code.
    # Construct from the (17,7,3) difference set D = {1, 2, 4, 8, 9, 13, 15}.
    # The [17,8,5] QR code is generated by the circulant matrix with first row
    # having 1s at positions in D.
    
    D = {1, 2, 4, 8, 9, 13, 15}
    
    # Build the 17x17 circulant matrix rows
    circ_rows = []
    for i in range(17):
        row = 0
        for j in range(17):
            if (j - i) % 17 in D:
                row |= (1 << j)
        circ_rows.append(row)
    
    # Extract 8 linearly independent rows from the circulant matrix
    # Use Gaussian elimination over GF(2)
    basis_17 = []
    for row in circ_rows:
        r = row
        for b in basis_17:
            # XOR to eliminate leading bits
            if r:
                msb = r.bit_length() - 1
                b_msb = b.bit_length() - 1
                if msb == b_msb:
                    r ^= b
                elif msb > b_msb:
                    # Need to find a basis vector with msb <= msb
                    pass
        # More careful Gaussian elimination
        # Let's redo this properly
        break
    
    # Proper Gaussian elimination to find rank and basis
    def gf2_rank_and_basis(rows):
        basis = []
        for row in rows:
            r = row
            for b in basis:
                if r == 0:
                    break
                # Find the highest set bit in r and b
                r_msb = r.bit_length() - 1
                b_msb = b.bit_length() - 1
                if r_msb == b_msb:
                    r ^= b
            if r != 0:
                basis.append(r)
        return basis
    
    basis_17 = gf2_rank_and_basis(circ_rows)
    
    # We expect rank 8 for the [17,8,5] QR code
    # If we don't have 8, we need to add more rows or use a different construction
    # The circulant matrix of the QR difference set should have rank 8
    
    if len(basis_17) < 8:
        # Try adding the all-ones vector and other structured vectors
        for i in range(17):
            v = (1 << i)
            basis_17 = gf2_rank_and_basis(basis_17 + [v])
            if len(basis_17) >= 8:
                break
        # Also try the all-ones vector
        ones = (1 << 17) - 1
        basis_17 = gf2_rank_and_basis(basis_17 + [ones])
    
    # Take the first 8 basis vectors
    basis_17 = basis_17[:8]
    
    # Extend to 18 bits by adding a parity check bit
    basis_18 = []
    for b in basis_17:
        parity = b.bit_count() % 2
        b18 = b | (parity << 17)
        basis_18.append(b18)
    
    # Add the 9th vector: the all-ones vector in 18 bits
    all_ones = (1 << 18) - 1
    basis_18.append(all_ones)
    
    # Generate all 512 codewords
    code_words = []
    for mask in range(1 << 9):
        w = 0
        for i in range(9):
            if (mask >> i) & 1:
                w ^= basis_18[i]
        code_words.append(w)
    
    # Verify the code
    valid = True
    for i in range(512):
        for j in range(i + 1, 512):
            d = (code_words[i] ^ code_words[j]).bit_count()
            if d < MIN_DISTANCE:
                valid = False
                break
        if not valid:
            break
    
    if valid:
        return code_words
    
    # Fallback: if the QR construction failed verification, use greedy search
    return greedy_construct()

def greedy_construct():
    """
    Fallback: Greedy search for a large linear code.
    """
    start_time = time.time()
    deadline = start_time + 50.0
    
    # Start with Reed-Muller RM(1,4) basis extended to 18 bits
    rm_basis = []
    # b0: all ones in first 16 bits
    b0 = 0
    for i in range(16):
        b0 |= 1 << i
    rm_basis.append(b0)
    
    # b1-b4: parity vectors
    for j in range(4):
        bj = 0
        for i in range(16):
            if (i >> j) & 1:
                bj |= 1 << i
        rm_basis.append(bj)
    
    basis = rm_basis.copy()
    
    # Try to extend to dimension 9
    for k in range(5, 9):
        if time.time() > deadline:
            break
            
        found = False
        attempts = 0
        max_attempts = 200000
        while attempts < max_attempts and not found:
            if time.time() > deadline:
                break
                
            cand = random.randint(0, (1 << N) - 1)
            
            min_d = N + 1
            for mask in range(1 << k):
                u = 0
                for i in range(k):
                    if (mask >> i) & 1:
                        u ^= basis[i]
                
                d = (cand ^ u).bit_count()
                if d < min_d:
                    min_d = d
                    if min_d < MIN_DISTANCE:
                        break
            
            if min_d >= MIN_DISTANCE:
                basis.append(cand)
                found = True
                break
            attempts += 1
            
        if not found:
            break
            
    if len(basis) == 0:
        return [0]
        
    dim = len(basis)
    code_words = []
    
    for mask in range(1 << dim):
        w = 0
        for i in range(dim):
            if (mask >> i) & 1:
                w ^= basis[i]
        code_words.append(w)
        
    return code_words

random.seed(42)
